# End-to-end MR-STAT reconstruction on the neural surrogate forward model.
#
# Run with:
#   source env.sh                          # binds PythonCall to the torch venv
#   julia --project=. scripts/run_recon.jl
#
# Two experiments on the same 120×120 phantom, both reconstructed with the
# surrogate-only objective:
#
#   (a) self-consistent: raw data generated by the surrogate itself. Data
#       and reconstruction share one forward model, so the recovered maps
#       must match the phantom up to solver tolerance — this validates the
#       whole pipeline (zero-copy bridge, ∂echos, J products, solver).
#
#   (b) EPG data: raw data generated by BlochSimulators' FISP3D simulation
#       (the scanner-like case; the same role the simulator will play for
#       real acquisitions). The reconstruction error now includes the
#       surrogate's approximation error (~0.5% NMAE on echos/derivatives).
#
# Figures land in scripts/output/.

ENV["MPLBACKEND"] = "Agg"   # matplotlib without a display; must precede PythonPlot

using MRSTAT
using MRSTAT.ForwardModels
using BlochSimulators
using ComputationalResources: CUDALibs
using CUDA
using StructArrays
using Statistics
using Printf
using PythonPlot

const OUTDIR = joinpath(@__DIR__, "output")
mkpath(OUTDIR)

surrogate = load_surrogate()
raw_data, coordinates, coils, trajectory, transmit_field, phantom =
    MRSTAT.generate_synthetic_data(surrogate)
N = isqrt(length(coordinates))

# Ground-truth maps (CPU) for error analysis.
T₁true = Array(phantom.T₁)
T₂true = Array(phantom.T₂)
ρtrue = abs.(complex.(Array(phantom.ρˣ), Array(phantom.ρʸ)))

function save_maps(T₁, T₂, ρ, label)
    fig, axs = subplots(1, 3; figsize = (13, 4))
    for (ax, img, ttl, vmax) in zip(axs, (T₁, T₂, ρ), ("T₁ (s)", "T₂ (s)", "|ρ|"),
                                    (2.6, 0.25, 1.6))
        im = ax.imshow(reshape(img, N, N); vmin = 0, vmax = vmax, cmap = "viridis")
        ax.set_title("$ttl — $label"); ax.axis("off")
        fig.colorbar(im; ax = ax, fraction = 0.046)
    end
    fig.tight_layout()
    path = joinpath(OUTDIR, "maps_$(replace(label, ' ' => '_')).png")
    fig.savefig(path; dpi = 150)
    PythonPlot.pyplot.close(fig)
    return path
end

save_maps(T₁true, T₂true, ρtrue, "ground truth")

function reconstruct_and_report(raw, label)
    println("═"^70)
    println("Reconstruction: $label")
    println("═"^70)
    t = @elapsed output = MRSTAT.mrstat_recon(raw, surrogate, coordinates, coils,
                                              trajectory, transmit_field)
    x = output.x[:, end]
    xm = reshape(x, :, 4)
    T₁ = exp.(xm[:, 1]); T₂ = exp.(xm[:, 2])
    ρ = abs.(complex.(xm[:, 3], xm[:, 4]))

    relerr(a, b) = 100 * median(abs.(a .- b) ./ abs.(b))
    maxerr(a, b) = 100 * quantile(abs.(a .- b) ./ abs.(b), 0.95)
    @printf("\n  %-28s %10s %10s\n", "$label ($(round(t; digits = 0)) s, $(size(output.x, 2) - 1) accepted steps)", "median", "p95")
    @printf("  %-28s %9.2f%% %9.2f%%\n", "T₁ relative error", relerr(T₁, T₁true), maxerr(T₁, T₁true))
    @printf("  %-28s %9.2f%% %9.2f%%\n", "T₂ relative error", relerr(T₂, T₂true), maxerr(T₂, T₂true))
    @printf("  %-28s %9.2f%% %9.2f%%\n", "|ρ| relative error", relerr(ρ, ρtrue), maxerr(ρ, ρtrue))
    println("  maps: ", save_maps(T₁, T₂, ρ, label))
    return (T₁ = T₁, T₂ = T₂, ρ = ρ, seconds = t)
end

# --- (a) self-consistent -----------------------------------------------------
res_self = reconstruct_and_report(raw_data, "surrogate data")

# --- (b) EPG-simulated raw data ---------------------------------------------
# The training sequence (frozen for this checkpoint; see validate_contract.jl).
neuralbloch_dir = neuralbloch_repo()
readvec(p) = [parse(Float64, l) for l in eachline(p) if !isempty(strip(l))]
flip_deg = readvec(joinpath(neuralbloch_dir, "data", "rf_data", "rf_angle_list.txt"))
phase_deg = readvec(joinpath(neuralbloch_dir, "data", "rf_data", "rf_phase_list.txt"))
rf_train = flip_deg .* exp.(1im .* deg2rad.(phase_deg))
sequence = gpu(f32(FISP3D(rf_train, 0.00558, 0.002745, 64, 0.01084, 0.000, 5, true, true, 1, 0.0)))

params_true = StructArray{T₁T₂B₁ρˣρʸ{Float32}}((
    phantom.T₁, phantom.T₂, gpu(f32(vec(transmit_field))), phantom.ρˣ, phantom.ρʸ))
echos_epg = simulate_magnetization(CUDALibs(), sequence, params_true)
phase_encoding!(echos_epg, trajectory, coordinates)
raw_epg = magnetization_to_signal(CUDALibs(), echos_epg, params_true, trajectory,
                                  coordinates, coils)

res_epg = reconstruct_and_report(raw_epg, "EPG data")

println("\nrun_recon finished — figures in $OUTDIR")
